/* From Uiverse.io by Cornerstone-04 - Tags: card */
.__UIV_SCOPE__ .cards {
  perspective: 500px;
}

.__UIV_SCOPE__ .card {
  width: 200px;
  height: 250px;
  background: #16161d;
  border: 2px solid #555555;
  border-radius: 4px;
  position: relative;
  transform-style: preserve-3d;
  will-change: transform;
  transition: transform .5s;
}

.__UIV_SCOPE__ .card:hover {
  transform: translateZ(10px) rotateX(20deg) rotateY(20deg);
}

.__UIV_SCOPE__ .card_title {
  color: #fff;
  position: absolute;
  top: 50%;
  right: 20px;
  transform: translateY(-50%);
  transition: transform .5s;
  font: 700 1.5rem monospace;
  text-shadow: -1px -1px 0 #000,  
    1px -1px 0 #000,
    -1px 1px 0 #000,
     1px 1px 0 #000;
}

.__UIV_SCOPE__ .card:hover .card_title {
  transform: translateZ(50px);
}
